#include <cstdio>
#include <cstring>
#include <cmath>
#include <cstdlib>
#include <vector>
#include <string>
#include <algorithm>
#include <queue>
#include <stack>
#include <deque>
#include <map>
#include <set>
#include <unordered_map>
#include <unordered_set>
#include <functional>
#include <numeric>
#include <sstream>
#include <iostream>
using namespace std;
int main(){int k;scanf("%d",&k);
vector<vector<long long>>arr(k);
for(int i=0;i<k;++i){int m;scanf("%d",&m);arr[i].resize(m);
for(int j=0;j<m;++j)scanf("%lld",&arr[i][j]);}
priority_queue<tuple<long long,int,int>,vector<tuple<long long,int,int>>,greater<>>pq;
for(int i=0;i<k;++i)if(!arr[i].empty())pq.push({arr[i][0],i,0});
bool first=true;
while(!pq.empty()){auto [v,i,j]=pq.top();pq.pop();
if(!first)printf(" ");printf("%lld",v);first=false;
if(j+1<(int)arr[i].size())pq.push({arr[i][j+1],i,j+1});}
printf("\n");return 0;}

